def build_dataset(words, stoi, block_size=3):
    X, Y = [], []
    context = [0] * block_size
    for w in words:
        for ch in list(w) + ["."]:
            ix = stoi[ch]
            X.append(context)
            Y.append(ix)
            context = context[1:] + [ix]
    return X, Y
